INSERT INTO page_definition (tenant_id, code, title, description, category, status) SELECT 1,'pico:gate-pass-detail','Gate Pass','Full gate-pass record + event history.','M10.Dispatch','PUBLISHED' WHERE NOT EXISTS (SELECT 1 FROM page_definition WHERE tenant_id=1 AND code='pico:gate-pass-detail');
INSERT INTO page_definition (tenant_id, code, title, description, category, status) SELECT 1,'pico:vehicle-detail','Vehicle','Vehicle record with fitness + tanker spec.','Master','PUBLISHED' WHERE NOT EXISTS (SELECT 1 FROM page_definition WHERE tenant_id=1 AND code='pico:vehicle-detail');
INSERT INTO page_definition (tenant_id, code, title, description, category, status) SELECT 1,'pico:driver-detail','Driver','Driver record with license + contact + history.','Master','PUBLISHED' WHERE NOT EXISTS (SELECT 1 FROM page_definition WHERE tenant_id=1 AND code='pico:driver-detail');
INSERT INTO page_definition (tenant_id, code, title, description, category, status) SELECT 1,'pico:tank-detail','Tank','Tank record with capacity + current grade.','Master','PUBLISHED' WHERE NOT EXISTS (SELECT 1 FROM page_definition WHERE tenant_id=1 AND code='pico:tank-detail');
INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at) SELECT p.id, 1, 'PUBLISHED', '{"kind":"detail","schemaVersion":2,"entity":"GatePass","idFrom":"route:id","dataSource":{"type":"entity","entity":"GatePass","filter":{"and":[{"field":"id","op":"eq","value":"route:id"},{"field":"tenant_id","op":"eq","value":"ctx:tenantId"}]},"select":["id","gp_number","flow_variant_code","vehicle_no","driver_name","driver_phone","vendor_id","status","current_step","workflow_instance_id","created_at","updated_at","closed_at","total_unloading_qty"]},"header":{"title":"GP {row.gp_number}","subtitle":"{row.flow_variant_code} • {row.vehicle_no}","statusBadge":{"field":"row.status","colorMap":{"DRAFT":"grey","GATE_PASS_CREATED":"blue","PARKING_IN":"blue","DISPATCH_QUEUED":"amber","QC_APPROVED":"green","QC_REJECTED":"red","WEIGHMENT_LOADED":"amber","UNLOADING_DONE":"green","CLOSED":"green"}}},"layout":[{"kind":"tabs","tabs":[{"label":"Summary","body":[{"kind":"section","title":"Vehicle + Driver","fields":[{"field":"vehicle_no","label":"Vehicle"},{"field":"driver_name","label":"Driver"},{"field":"driver_phone","label":"Phone"}]},{"kind":"section","title":"Workflow","fields":[{"field":"current_step","label":"Current Step"},{"field":"workflow_instance_id","label":"Instance #"},{"field":"created_at","label":"Created","render":"datetime"},{"field":"updated_at","label":"Updated","render":"datetime"}]}]},{"label":"Activity","body":[{"kind":"list","dataSource":{"type":"entity","entity":"WorkflowEvent","filter":{"and":[{"field":"instance_id","op":"eq","value":"row.workflow_instance_id"}]},"select":["ts","kind","from_state","to_state","page_code"]},"columns":[{"field":"ts","label":"When","render":"datetime"},{"field":"kind","label":"Kind","render":"badge"},{"field":"from_state","label":"From"},{"field":"to_state","label":"To"},{"field":"page_code","label":"Page"}],"sort":{"default":[{"field":"ts","dir":"desc"}]},"pagination":{"kind":"server","pageSize":50}}]}]}]}', 'V7_11', CURRENT_TIMESTAMP FROM page_definition p WHERE p.tenant_id=1 AND p.code='pico:gate-pass-detail' AND NOT EXISTS (SELECT 1 FROM page_version v WHERE v.page_id = p.id AND v.version = 1);
INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at) SELECT p.id, 1, 'PUBLISHED', '{"kind":"detail","schemaVersion":2,"entity":"Vehicle","idFrom":"route:id","dataSource":{"type":"entity","entity":"Vehicle","filter":{"and":[{"field":"id","op":"eq","value":"route:id"}]},"select":["id","registration_no","ownership","vehicle_type","tanker_compartments","tare_weight_kg","capacity_kg","transporter_name","rc_expiry","insurance_expiry","puc_expiry","tank_cleaning_cert_no","tank_cleaning_cert_expiry","active"]},"header":{"title":"{row.registration_no}","subtitle":"{row.ownership} • {row.vehicle_type}","statusBadge":{"field":"row.active","colorMap":{"1":"green","0":"red"}}},"layout":[{"kind":"section","title":"Tanker","fields":[{"field":"capacity_kg","label":"Capacity (kg)"},{"field":"tare_weight_kg","label":"Tare (kg)"},{"field":"tanker_compartments","label":"Compartments"}]},{"kind":"section","title":"Compliance","fields":[{"field":"rc_expiry","label":"RC Expiry","render":"date"},{"field":"insurance_expiry","label":"Insurance Expiry","render":"date"},{"field":"puc_expiry","label":"PUC Expiry","render":"date"},{"field":"tank_cleaning_cert_no","label":"Tank Cleaning Cert #"},{"field":"tank_cleaning_cert_expiry","label":"Cleaning Expiry","render":"date"}]},{"kind":"section","title":"Transporter","fields":[{"field":"transporter_name","label":"Transporter (if hired)"}]}]}', 'V7_11', CURRENT_TIMESTAMP FROM page_definition p WHERE p.tenant_id=1 AND p.code='pico:vehicle-detail' AND NOT EXISTS (SELECT 1 FROM page_version v WHERE v.page_id = p.id AND v.version = 1);
INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at) SELECT p.id, 1, 'PUBLISHED', '{"kind":"detail","schemaVersion":2,"entity":"Driver","idFrom":"route:id","dataSource":{"type":"entity","entity":"Driver","filter":{"and":[{"field":"id","op":"eq","value":"route:id"}]},"select":["id","name","dl_number","dl_expiry","primary_mobile","alt_mobile","preferred_language","aadhaar_last4","active"]},"header":{"title":"{row.name}","subtitle":"DL {row.dl_number}","statusBadge":{"field":"row.active","colorMap":{"1":"green","0":"red"}}},"layout":[{"kind":"section","title":"Identity","fields":[{"field":"name","label":"Name"},{"field":"dl_number","label":"DL Number"},{"field":"dl_expiry","label":"DL Expiry","render":"date"},{"field":"aadhaar_last4","label":"Aadhaar (last 4)"}]},{"kind":"section","title":"Contact","fields":[{"field":"primary_mobile","label":"Primary Mobile"},{"field":"alt_mobile","label":"Alternate Mobile"},{"field":"preferred_language","label":"Language"}]}]}', 'V7_11', CURRENT_TIMESTAMP FROM page_definition p WHERE p.tenant_id=1 AND p.code='pico:driver-detail' AND NOT EXISTS (SELECT 1 FROM page_version v WHERE v.page_id = p.id AND v.version = 1);
INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at) SELECT p.id, 1, 'PUBLISHED', '{"kind":"detail","schemaVersion":2,"entity":"TankLocation","idFrom":"route:id","dataSource":{"type":"entity","entity":"TankLocation","filter":{"and":[{"field":"id","op":"eq","value":"route:id"}]},"select":["id","code","tank_capacity_kl","current_oil_grade","min_headspace_kl","batch_density","last_cleaned_on","active"]},"header":{"title":"{row.code}","subtitle":"Grade: {row.current_oil_grade}","statusBadge":{"field":"row.active","colorMap":{"1":"green","0":"red"}}},"layout":[{"kind":"section","title":"Capacity","fields":[{"field":"tank_capacity_kl","label":"Capacity (kL)"},{"field":"min_headspace_kl","label":"Min Headspace (kL)"}]},{"kind":"section","title":"Current Batch","fields":[{"field":"current_oil_grade","label":"Grade"},{"field":"batch_density","label":"Density (g/cc)"},{"field":"last_cleaned_on","label":"Last Cleaned","render":"date"}]}]}', 'V7_11', CURRENT_TIMESTAMP FROM page_definition p WHERE p.tenant_id=1 AND p.code='pico:tank-detail' AND NOT EXISTS (SELECT 1 FROM page_version v WHERE v.page_id = p.id AND v.version = 1);
