-- =====================================================================
-- V7_11 — Detail-view pages for the master entities.
-- Each detail page binds id from URL (route:id) and renders sections of
-- fields. Linking back from the list pages comes via the existing
-- linkTo:"page:..." pattern in the list column config.
-- =====================================================================






UPDATE page_definition SET current_version_id = (SELECT id FROM page_version WHERE page_id = page_definition.id AND version = 1 LIMIT 1) WHERE tenant_id=1 AND code IN ('pico:gate-pass-detail','pico:vehicle-detail','pico:driver-detail','pico:tank-detail') AND current_version_id IS NULL;
